
-- Phase 4A: business-document lifecycle and authoritative posting.
-- All mutations remain behind owner-scoped RPCs; tables remain read-only to clients.
alter table public.open_items add column remaining_amount numeric(20,6) not null default 0 check (remaining_amount >= 0);
update public.open_items set remaining_amount = original_amount where remaining_amount = 0;

create or replace function public.create_customer(p_organization_id uuid,p_name text,p_trn text default null,p_email text default null,p_phone text default null,p_billing_address text default null,p_payment_terms_days integer default 30) returns uuid language plpgsql security definer set search_path=pg_catalog,public as $$ declare v_id uuid:=gen_random_uuid(); begin perform public.assert_accounting_owner(p_organization_id); if nullif(trim(p_name),'') is null or p_payment_terms_days<0 then raise exception 'invalid_customer'; end if; insert into public.customers(id,organization_id,name,trn,email,phone,billing_address,payment_terms_days,created_by) values(v_id,p_organization_id,trim(p_name),nullif(trim(p_trn),''),nullif(trim(p_email),''),nullif(trim(p_phone),''),nullif(trim(p_billing_address),''),p_payment_terms_days,auth.uid()); perform public.accounting_audit(p_organization_id,'customer.created','customer',v_id); return v_id; end; $$;
create or replace function public.update_customer(p_organization_id uuid,p_customer_id uuid,p_name text,p_trn text default null,p_email text default null,p_phone text default null,p_billing_address text default null,p_payment_terms_days integer default 30,p_is_active boolean default true) returns void language plpgsql security definer set search_path=pg_catalog,public as $$ begin perform public.assert_accounting_owner(p_organization_id); if nullif(trim(p_name),'') is null or p_payment_terms_days<0 then raise exception 'invalid_customer'; end if; update public.customers set name=trim(p_name),trn=nullif(trim(p_trn),''),email=nullif(trim(p_email),''),phone=nullif(trim(p_phone),''),billing_address=nullif(trim(p_billing_address),''),payment_terms_days=p_payment_terms_days,is_active=p_is_active where id=p_customer_id and organization_id=p_organization_id; if not found then raise exception 'not_found'; end if; perform public.accounting_audit(p_organization_id,'customer.updated','customer',p_customer_id); end; $$;
create or replace function public.create_supplier(p_organization_id uuid,p_name text,p_trn text default null,p_email text default null,p_phone text default null,p_billing_address text default null,p_payment_terms_days integer default 30) returns uuid language plpgsql security definer set search_path=pg_catalog,public as $$ declare v_id uuid:=gen_random_uuid(); begin perform public.assert_accounting_owner(p_organization_id); if nullif(trim(p_name),'') is null or p_payment_terms_days<0 then raise exception 'invalid_supplier'; end if; insert into public.suppliers(id,organization_id,name,trn,email,phone,billing_address,payment_terms_days,created_by) values(v_id,p_organization_id,trim(p_name),nullif(trim(p_trn),''),nullif(trim(p_email),''),nullif(trim(p_phone),''),nullif(trim(p_billing_address),''),p_payment_terms_days,auth.uid()); perform public.accounting_audit(p_organization_id,'supplier.created','supplier',v_id); return v_id; end; $$;
create or replace function public.update_supplier(p_organization_id uuid,p_supplier_id uuid,p_name text,p_trn text default null,p_email text default null,p_phone text default null,p_billing_address text default null,p_payment_terms_days integer default 30,p_is_active boolean default true) returns void language plpgsql security definer set search_path=pg_catalog,public as $$ begin perform public.assert_accounting_owner(p_organization_id); if nullif(trim(p_name),'') is null or p_payment_terms_days<0 then raise exception 'invalid_supplier'; end if; update public.suppliers set name=trim(p_name),trn=nullif(trim(p_trn),''),email=nullif(trim(p_email),''),phone=nullif(trim(p_phone),''),billing_address=nullif(trim(p_billing_address),''),payment_terms_days=p_payment_terms_days,is_active=p_is_active where id=p_supplier_id and organization_id=p_organization_id; if not found then raise exception 'not_found'; end if; perform public.accounting_audit(p_organization_id,'supplier.updated','supplier',p_supplier_id); end; $$;

create or replace function public.replace_sales_invoice_lines(p_organization_id uuid,p_invoice_id uuid,p_lines jsonb) returns void language plpgsql security definer set search_path=pg_catalog,public as $$ declare x jsonb; begin if jsonb_typeof(p_lines)<>'array' or jsonb_array_length(p_lines)=0 then raise exception 'invoice_lines_required'; end if; delete from public.sales_invoice_lines where invoice_id=p_invoice_id; for x in select value from jsonb_array_elements(p_lines) loop insert into public.sales_invoice_lines(invoice_id,organization_id,description,quantity,unit_price,discount,tax_rate_id,revenue_account_id) values(p_invoice_id,p_organization_id,trim(x->>'description'),(x->>'quantity')::numeric,(x->>'unit_price')::numeric,coalesce((x->>'discount')::numeric,0),nullif(x->>'tax_rate_id','')::uuid,nullif(x->>'revenue_account_id','')::uuid); end loop; end; $$;
create or replace function public.replace_purchase_bill_lines(p_organization_id uuid,p_bill_id uuid,p_lines jsonb) returns void language plpgsql security definer set search_path=pg_catalog,public as $$ declare x jsonb; begin if jsonb_typeof(p_lines)<>'array' or jsonb_array_length(p_lines)=0 then raise exception 'bill_lines_required'; end if; delete from public.purchase_bill_lines where bill_id=p_bill_id; for x in select value from jsonb_array_elements(p_lines) loop insert into public.purchase_bill_lines(bill_id,organization_id,description,quantity,unit_price,discount,tax_rate_id,expense_account_id) values(p_bill_id,p_organization_id,trim(x->>'description'),(x->>'quantity')::numeric,(x->>'unit_price')::numeric,coalesce((x->>'discount')::numeric,0),nullif(x->>'tax_rate_id','')::uuid,(x->>'expense_account_id')::uuid); end loop; end; $$;

create or replace function public.create_sales_invoice_draft(p_organization_id uuid,p_customer_id uuid,p_invoice_date date,p_due_date date,p_lines jsonb,p_branch_id uuid default null,p_reference text default null,p_notes text default null) returns uuid language plpgsql security definer set search_path=pg_catalog,public as $$ declare v_id uuid:=gen_random_uuid(); begin perform public.assert_accounting_owner(p_organization_id); if p_due_date<p_invoice_date or not exists(select 1 from public.customers where id=p_customer_id and organization_id=p_organization_id and is_active) or (p_branch_id is not null and not exists(select 1 from public.branches where id=p_branch_id and organization_id=p_organization_id)) then raise exception 'invalid_invoice_reference'; end if; insert into public.sales_invoices(id,organization_id,branch_id,customer_id,invoice_date,due_date,reference,notes,created_by) values(v_id,p_organization_id,p_branch_id,p_customer_id,p_invoice_date,p_due_date,nullif(trim(p_reference),''),nullif(trim(p_notes),''),auth.uid()); perform public.replace_sales_invoice_lines(p_organization_id,v_id,p_lines); perform public.accounting_audit(p_organization_id,'sales_invoice.created','sales_invoice',v_id); return v_id; end; $$;
create or replace function public.update_sales_invoice_draft(p_organization_id uuid,p_invoice_id uuid,p_customer_id uuid,p_invoice_date date,p_due_date date,p_lines jsonb,p_branch_id uuid default null,p_reference text default null,p_notes text default null) returns void language plpgsql security definer set search_path=pg_catalog,public as $$ begin perform public.assert_accounting_owner(p_organization_id); if p_due_date<p_invoice_date or not exists(select 1 from public.customers where id=p_customer_id and organization_id=p_organization_id and is_active) or (p_branch_id is not null and not exists(select 1 from public.branches where id=p_branch_id and organization_id=p_organization_id)) then raise exception 'invalid_invoice_reference'; end if; update public.sales_invoices set customer_id=p_customer_id,branch_id=p_branch_id,invoice_date=p_invoice_date,due_date=p_due_date,reference=nullif(trim(p_reference),''),notes=nullif(trim(p_notes),'') where id=p_invoice_id and organization_id=p_organization_id and status='draft'; if not found then raise exception 'invoice_not_editable'; end if; perform public.replace_sales_invoice_lines(p_organization_id,p_invoice_id,p_lines); perform public.accounting_audit(p_organization_id,'sales_invoice.updated','sales_invoice',p_invoice_id); end; $$;
create or replace function public.delete_sales_invoice_draft(p_organization_id uuid,p_invoice_id uuid) returns void language plpgsql security definer set search_path=pg_catalog,public as $$ begin perform public.assert_accounting_owner(p_organization_id); delete from public.sales_invoices where id=p_invoice_id and organization_id=p_organization_id and status='draft'; if not found then raise exception 'invoice_not_editable'; end if; end; $$;

create or replace function public.create_purchase_bill_draft(p_organization_id uuid,p_supplier_id uuid,p_bill_date date,p_due_date date,p_lines jsonb,p_branch_id uuid default null,p_reference text default null,p_notes text default null) returns uuid language plpgsql security definer set search_path=pg_catalog,public as $$ declare v_id uuid:=gen_random_uuid(); begin perform public.assert_accounting_owner(p_organization_id); if p_due_date<p_bill_date or not exists(select 1 from public.suppliers where id=p_supplier_id and organization_id=p_organization_id and is_active) or (p_branch_id is not null and not exists(select 1 from public.branches where id=p_branch_id and organization_id=p_organization_id)) then raise exception 'invalid_bill_reference'; end if; insert into public.purchase_bills(id,organization_id,branch_id,supplier_id,bill_date,due_date,reference,notes,created_by) values(v_id,p_organization_id,p_branch_id,p_supplier_id,p_bill_date,p_due_date,nullif(trim(p_reference),''),nullif(trim(p_notes),''),auth.uid()); perform public.replace_purchase_bill_lines(p_organization_id,v_id,p_lines); perform public.accounting_audit(p_organization_id,'purchase_bill.created','purchase_bill',v_id); return v_id; end; $$;
create or replace function public.update_purchase_bill_draft(p_organization_id uuid,p_bill_id uuid,p_supplier_id uuid,p_bill_date date,p_due_date date,p_lines jsonb,p_branch_id uuid default null,p_reference text default null,p_notes text default null) returns void language plpgsql security definer set search_path=pg_catalog,public as $$ begin perform public.assert_accounting_owner(p_organization_id); if p_due_date<p_bill_date or not exists(select 1 from public.suppliers where id=p_supplier_id and organization_id=p_organization_id and is_active) or (p_branch_id is not null and not exists(select 1 from public.branches where id=p_branch_id and organization_id=p_organization_id)) then raise exception 'invalid_bill_reference'; end if; update public.purchase_bills set supplier_id=p_supplier_id,branch_id=p_branch_id,bill_date=p_bill_date,due_date=p_due_date,reference=nullif(trim(p_reference),''),notes=nullif(trim(p_notes),'') where id=p_bill_id and organization_id=p_organization_id and status='draft'; if not found then raise exception 'bill_not_editable'; end if; perform public.replace_purchase_bill_lines(p_organization_id,p_bill_id,p_lines); perform public.accounting_audit(p_organization_id,'purchase_bill.updated','purchase_bill',p_bill_id); end; $$;
create or replace function public.delete_purchase_bill_draft(p_organization_id uuid,p_bill_id uuid) returns void language plpgsql security definer set search_path=pg_catalog,public as $$ begin perform public.assert_accounting_owner(p_organization_id); delete from public.purchase_bills where id=p_bill_id and organization_id=p_organization_id and status='draft'; if not found then raise exception 'bill_not_editable'; end if; end; $$;

-- Phase 3 remains the sole journal poster.  Business sources may use protected
-- system accounts; manual journals still cannot.
create or replace function public.post_journal_entry(p_organization_id uuid,p_journal_id uuid) returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$ declare j public.journal_entries%rowtype; v_debit numeric; v_credit numeric; v_number bigint; v_prefix text; v_padding smallint; v_suffix text; begin perform public.assert_accounting_owner(p_organization_id); select * into j from public.journal_entries where id=p_journal_id and organization_id=p_organization_id for update; if not found then raise exception 'not_found'; end if; if j.status='posted' then return jsonb_build_object('journal_id',j.id,'already_posted',true,'journal_number',j.journal_number); end if; if j.status<>'draft' then raise exception 'journal_not_postable'; end if; select coalesce(sum(debit_amount),0),coalesce(sum(credit_amount),0) into v_debit,v_credit from public.journal_lines where journal_entry_id=j.id; if v_debit<=0 or v_debit<>v_credit or (select count(*) from public.journal_lines where journal_entry_id=j.id)<2 then raise exception 'journal_not_balanced'; end if; select fy.id into j.financial_year_id from public.financial_years fy where fy.organization_id=p_organization_id and j.journal_date between fy.start_date and fy.end_date and fy.status='open'; if j.financial_year_id is null then raise exception 'financial_year_closed_or_missing'; end if; if exists(select 1 from public.journal_lines l left join public.accounts a on a.id=l.account_id and a.organization_id=p_organization_id where l.journal_entry_id=j.id and (a.id is null or not a.is_active or (j.source_type='manual_journal' and not a.allow_manual_posting))) then raise exception 'invalid_posting_account'; end if; select prefix,padding,suffix,next_number into v_prefix,v_padding,v_suffix,v_number from public.document_sequences where organization_id=p_organization_id and document_type='journal' and branch_id is null and financial_year_id is null for update; if v_number is null then raise exception 'journal_sequence_missing'; end if; update public.document_sequences set next_number=next_number+1 where organization_id=p_organization_id and document_type='journal' and branch_id is null and financial_year_id is null; update public.journal_entries set financial_year_id=j.financial_year_id,journal_number=v_prefix||lpad(v_number::text,v_padding,'0')||coalesce(v_suffix,''),status='posted',posted_at=now(),posted_by=auth.uid() where id=j.id; perform public.accounting_audit(p_organization_id,'journal.posted','journal_entry',j.id); return jsonb_build_object('journal_id',j.id,'already_posted',false,'journal_number',v_prefix||lpad(v_number::text,v_padding,'0')||coalesce(v_suffix,'')); end; $$;

create or replace function public.post_sales_invoice(p_organization_id uuid,p_invoice_id uuid) returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$ declare d public.sales_invoices%rowtype; l public.sales_invoice_lines%rowtype; v_journal uuid:=gen_random_uuid(); v_ar uuid; v_revenue uuid; v_output_vat uuid; v_account uuid; v_tax public.tax_rates%rowtype; v_amount numeric(20,6); v_tax_amount numeric(20,6); v_subtotal numeric(20,6):=0; v_tax_total numeric(20,6):=0; v_number bigint; v_prefix text; v_padding smallint; v_suffix text; v_line_number smallint:=0; begin perform public.assert_accounting_owner(p_organization_id); select * into d from public.sales_invoices where id=p_invoice_id and organization_id=p_organization_id for update; if not found then raise exception 'not_found'; end if; if d.status='posted' then return jsonb_build_object('invoice_id',d.id,'journal_id',d.posted_journal_id,'invoice_number',d.invoice_number,'already_posted',true); end if; if d.status<>'draft' or not exists(select 1 from public.customers where id=d.customer_id and organization_id=p_organization_id and is_active) or (d.branch_id is not null and not exists(select 1 from public.branches where id=d.branch_id and organization_id=p_organization_id)) then raise exception 'invoice_not_postable'; end if; select id into v_ar from public.accounts where organization_id=p_organization_id and system_key='accounts_receivable' and is_active; select id into v_revenue from public.accounts where organization_id=p_organization_id and system_key='sales_revenue' and is_active; select id into v_output_vat from public.accounts where organization_id=p_organization_id and system_key='output_vat' and is_active; if v_ar is null or v_revenue is null or v_output_vat is null then raise exception 'system_account_missing'; end if; insert into public.journal_entries(id,organization_id,branch_id,journal_date,source_type,source_id,description,created_by) values(v_journal,p_organization_id,d.branch_id,d.invoice_date,'sales_invoice',d.id,'Sales invoice',auth.uid()); for l in select * from public.sales_invoice_lines where invoice_id=d.id order by id loop v_amount:=round(l.quantity*l.unit_price-l.discount,6); if v_amount<0 then raise exception 'invalid_invoice_line'; end if; v_account:=coalesce(l.revenue_account_id,v_revenue); if not exists(select 1 from public.accounts where id=v_account and organization_id=p_organization_id and is_active) then raise exception 'invalid_revenue_account'; end if; v_tax_amount:=0; if l.tax_rate_id is not null then select * into v_tax from public.tax_rates where id=l.tax_rate_id and organization_id=p_organization_id and sales_enabled and is_active; if not found then raise exception 'invalid_sales_tax_rate'; end if; v_tax_amount:=round(v_amount*v_tax.rate_percent/100,6); end if; v_subtotal:=v_subtotal+v_amount; v_tax_total:=v_tax_total+v_tax_amount; v_line_number:=v_line_number+1; insert into public.journal_lines(organization_id,journal_entry_id,line_number,account_id,description,debit_amount,credit_amount,tax_rate_id,tax_amount,party_type,party_id,branch_id) values(p_organization_id,v_journal,v_line_number,v_account,l.description,0,v_amount,l.tax_rate_id,v_tax_amount,'customer',d.customer_id,d.branch_id); if v_tax_amount<>0 then v_line_number:=v_line_number+1; insert into public.journal_lines(organization_id,journal_entry_id,line_number,account_id,description,debit_amount,credit_amount,tax_rate_id,tax_amount,party_type,party_id,branch_id) values(p_organization_id,v_journal,v_line_number,v_output_vat,'VAT: '||l.description,0,v_tax_amount,l.tax_rate_id,v_tax_amount,'customer',d.customer_id,d.branch_id); end if; end loop; if v_line_number=0 then raise exception 'invoice_lines_required'; end if; select prefix,padding,suffix,next_number into v_prefix,v_padding,v_suffix,v_number from public.document_sequences where organization_id=p_organization_id and document_type='sales_invoice' and branch_id is null and financial_year_id is null for update; if v_number is null then raise exception 'invoice_sequence_missing'; end if; update public.document_sequences set next_number=next_number+1 where organization_id=p_organization_id and document_type='sales_invoice' and branch_id is null and financial_year_id is null; update public.journal_entries set reference=v_prefix||lpad(v_number::text,v_padding,'0')||coalesce(v_suffix,'') where id=v_journal; v_line_number:=v_line_number+1; insert into public.journal_lines(organization_id,journal_entry_id,line_number,account_id,description,debit_amount,credit_amount,party_type,party_id,branch_id) values(p_organization_id,v_journal,v_line_number,v_ar,'Accounts receivable',v_subtotal+v_tax_total,0,'customer',d.customer_id,d.branch_id); perform public.post_journal_entry(p_organization_id,v_journal); update public.sales_invoices set invoice_number=v_prefix||lpad(v_number::text,v_padding,'0')||coalesce(v_suffix,''),subtotal=v_subtotal,tax_total=v_tax_total,grand_total=v_subtotal+v_tax_total,status='posted',posted_journal_id=v_journal,posted_at=now(),posted_by=auth.uid() where id=d.id; insert into public.open_items(organization_id,kind,customer_id,source_journal_id,source_document_id,original_amount,remaining_amount,due_date) values(p_organization_id,'receivable',d.customer_id,v_journal,d.id,v_subtotal+v_tax_total,v_subtotal+v_tax_total,d.due_date); perform public.accounting_audit(p_organization_id,'sales_invoice.posted','sales_invoice',d.id,jsonb_build_object('journal_id',v_journal)); return jsonb_build_object('invoice_id',d.id,'journal_id',v_journal,'invoice_number',v_prefix||lpad(v_number::text,v_padding,'0')||coalesce(v_suffix,''),'already_posted',false); end; $$;

create or replace function public.post_purchase_bill(p_organization_id uuid,p_bill_id uuid) returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$ declare d public.purchase_bills%rowtype; l public.purchase_bill_lines%rowtype; v_journal uuid:=gen_random_uuid(); v_ap uuid; v_input_vat uuid; v_tax public.tax_rates%rowtype; v_amount numeric(20,6); v_tax_amount numeric(20,6); v_subtotal numeric(20,6):=0; v_tax_total numeric(20,6):=0; v_number bigint; v_prefix text; v_padding smallint; v_suffix text; v_line_number smallint:=0; begin perform public.assert_accounting_owner(p_organization_id); select * into d from public.purchase_bills where id=p_bill_id and organization_id=p_organization_id for update; if not found then raise exception 'not_found'; end if; if d.status='posted' then return jsonb_build_object('bill_id',d.id,'journal_id',d.posted_journal_id,'bill_number',d.bill_number,'already_posted',true); end if; if d.status<>'draft' or not exists(select 1 from public.suppliers where id=d.supplier_id and organization_id=p_organization_id and is_active) or (d.branch_id is not null and not exists(select 1 from public.branches where id=d.branch_id and organization_id=p_organization_id)) then raise exception 'bill_not_postable'; end if; select id into v_ap from public.accounts where organization_id=p_organization_id and system_key='accounts_payable' and is_active; select id into v_input_vat from public.accounts where organization_id=p_organization_id and system_key='input_vat' and is_active; if v_ap is null or v_input_vat is null then raise exception 'system_account_missing'; end if; insert into public.journal_entries(id,organization_id,branch_id,journal_date,source_type,source_id,description,created_by) values(v_journal,p_organization_id,d.branch_id,d.bill_date,'purchase_bill',d.id,'Purchase bill',auth.uid()); for l in select * from public.purchase_bill_lines where bill_id=d.id order by id loop v_amount:=round(l.quantity*l.unit_price-l.discount,6); if v_amount<0 or not exists(select 1 from public.accounts where id=l.expense_account_id and organization_id=p_organization_id and is_active) then raise exception 'invalid_purchase_line'; end if; v_tax_amount:=0; if l.tax_rate_id is not null then select * into v_tax from public.tax_rates where id=l.tax_rate_id and organization_id=p_organization_id and purchase_enabled and is_active; if not found then raise exception 'invalid_purchase_tax_rate'; end if; v_tax_amount:=round(v_amount*v_tax.rate_percent/100,6); end if; v_subtotal:=v_subtotal+v_amount; v_tax_total:=v_tax_total+v_tax_amount; v_line_number:=v_line_number+1; insert into public.journal_lines(organization_id,journal_entry_id,line_number,account_id,description,debit_amount,credit_amount,tax_rate_id,tax_amount,party_type,party_id,branch_id) values(p_organization_id,v_journal,v_line_number,l.expense_account_id,l.description,v_amount,0,l.tax_rate_id,v_tax_amount,'supplier',d.supplier_id,d.branch_id); if v_tax_amount<>0 then v_line_number:=v_line_number+1; insert into public.journal_lines(organization_id,journal_entry_id,line_number,account_id,description,debit_amount,credit_amount,tax_rate_id,tax_amount,party_type,party_id,branch_id) values(p_organization_id,v_journal,v_line_number,v_input_vat,'VAT: '||l.description,v_tax_amount,0,l.tax_rate_id,v_tax_amount,'supplier',d.supplier_id,d.branch_id); end if; end loop; if v_line_number=0 then raise exception 'bill_lines_required'; end if; perform public.ensure_business_document_sequences(p_organization_id); select prefix,padding,suffix,next_number into v_prefix,v_padding,v_suffix,v_number from public.document_sequences where organization_id=p_organization_id and document_type='purchase_bill' and branch_id is null and financial_year_id is null for update; if v_number is null then raise exception 'bill_sequence_missing'; end if; update public.document_sequences set next_number=next_number+1 where organization_id=p_organization_id and document_type='purchase_bill' and branch_id is null and financial_year_id is null; update public.journal_entries set reference=v_prefix||lpad(v_number::text,v_padding,'0')||coalesce(v_suffix,'') where id=v_journal; v_line_number:=v_line_number+1; insert into public.journal_lines(organization_id,journal_entry_id,line_number,account_id,description,debit_amount,credit_amount,party_type,party_id,branch_id) values(p_organization_id,v_journal,v_line_number,v_ap,'Accounts payable',0,v_subtotal+v_tax_total,'supplier',d.supplier_id,d.branch_id); perform public.post_journal_entry(p_organization_id,v_journal); update public.purchase_bills set bill_number=v_prefix||lpad(v_number::text,v_padding,'0')||coalesce(v_suffix,''),subtotal=v_subtotal,tax_total=v_tax_total,grand_total=v_subtotal+v_tax_total,status='posted',posted_journal_id=v_journal,posted_at=now(),posted_by=auth.uid() where id=d.id; insert into public.open_items(organization_id,kind,supplier_id,source_journal_id,source_document_id,original_amount,remaining_amount,due_date) values(p_organization_id,'payable',d.supplier_id,v_journal,d.id,v_subtotal+v_tax_total,v_subtotal+v_tax_total,d.due_date); perform public.accounting_audit(p_organization_id,'purchase_bill.posted','purchase_bill',d.id,jsonb_build_object('journal_id',v_journal)); return jsonb_build_object('bill_id',d.id,'journal_id',v_journal,'bill_number',v_prefix||lpad(v_number::text,v_padding,'0')||coalesce(v_suffix,''),'already_posted',false); end; $$;

create trigger customers_phase4a_updated before update on public.customers for each row execute function public.set_updated_at();
create trigger suppliers_phase4a_updated before update on public.suppliers for each row execute function public.set_updated_at();
create trigger sales_invoices_phase4a_updated before update on public.sales_invoices for each row execute function public.set_updated_at();
create trigger purchase_bills_phase4a_updated before update on public.purchase_bills for each row execute function public.set_updated_at();
