grant execute on function public.create_customer(uuid,text,text,text,text,text,integer),public.update_customer(uuid,uuid,text,text,text,text,text,integer,boolean),public.create_supplier(uuid,text,text,text,text,text,integer),public.update_supplier(uuid,uuid,text,text,text,text,text,integer,boolean),public.create_sales_invoice_draft(uuid,uuid,date,date,jsonb,uuid,text,text),public.update_sales_invoice_draft(uuid,uuid,uuid,date,date,jsonb,uuid,text,text),public.delete_sales_invoice_draft(uuid,uuid),public.create_purchase_bill_draft(uuid,uuid,date,date,jsonb,uuid,text,text),public.update_purchase_bill_draft(uuid,uuid,uuid,date,date,jsonb,uuid,text,text),public.delete_purchase_bill_draft(uuid,uuid),public.post_sales_invoice(uuid,uuid),public.post_purchase_bill(uuid,uuid) to authenticated;
